import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import crypto from 'node:crypto';import {NativeHomeSession} from '../session.mjs';import {createUITicket} from '../ui-ticket.mjs';
const root=new URL('../',import.meta.url),read=n=>JSON.parse(fs.readFileSync(new URL(n,root))),c=read('contract.json'),masks=Object.fromEntries(Object.entries(c.masks).map(([k,s])=>[k,new Uint8Array(fs.readFileSync(new URL(s.path,root)))]));
const make=(id,extra={})=>new NativeHomeSession({contract:c,homeId:id,masks,...extra});function walk(s,path){assert.deepEqual(s.foot,path[0]);for(const to of path.slice(1)){const[x,y]=s.foot;assert.equal(Math.abs(x-to[0])+Math.abs(y-to[1]),1);assert.equal(s.move(to[0]<x?'left':to[0]>x?'right':to[1]<y?'up':'down').ok,true)}}
async function enter(s){s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);assert.equal((await s.action()).kind,'enter');s.releaseAction()}
function exitRoute(s){const f=c.floors[s.scene],at=s.foot.join(','),key=Object.keys(f.routes).find(k=>k.endsWith('_entry')&&f.routes[k][0].join(',')===at);assert(key,'selected arrival to exit route');walk(s,f.routes[key]);s.face('down')}
test('original source pins exact and conversion safe49 mask has unchanged semantics',()=>{const p=read('INPUT_PINS.json');for(const[path,sha]of Object.entries(p.pins))assert.equal(crypto.createHash('sha256').update(fs.readFileSync(new URL('../'+path,root))).digest('hex'),sha,path);assert.equal(c.worldConnected,false);assert.equal(c.saveConnected,false);assert.equal(masks.exterior.length,5120*1536)});
for(const id of Object.keys(c.houses)){
 test(id+': all existing support path points; exact new entry/return and floor identity',async()=>{const s=make(id);walk(s,s.h.exteriorDoor.approachRoute);assert.equal((await s.action()).reason,'DOOR_CLOSED');s.releaseAction();s.setDoorState('OPEN');assert.equal((await s.action()).kind,'enter');s.releaseAction();assert.equal(s.scene,s.h.firstFloor);assert.deepEqual(s.foot,s.h.interiorDoor.arrival);exitRoute(s);assert.equal((await s.action()).kind,'return');assert.deepEqual(s.foot,s.h.exteriorDoor.arrival);assert.equal(s.snapshot().worldConnected,false)});
 test(id+': BLOCKED refuses entry without location mutation',async()=>{const s=make(id);s.setDoorState('BLOCKED');walk(s,s.h.exteriorDoor.approachRoute);const old=s.foot.slice();assert.equal((await s.action()).reason,'DOOR_BLOCKED');assert.deepEqual(s.foot,old);assert.equal(s.portalTransfers,0)});
 test(id+': repeated/held actions do not chain and10 visits preserve landings',async()=>{const s=make(id);for(let i=0;i<10;i++){await enter(s);assert.equal((await s.action()).ok,false);s.releaseAction();exitRoute(s);assert.equal((await s.action()).kind,'return');assert.equal((await s.action()).ok,false);s.releaseAction();assert.deepEqual(s.foot,s.h.exteriorDoor.arrival)}assert.equal(s.portalTransfers,20)});
 test(id+': wrong facing/adjacent position is not an entry',async()=>{const s=make(id);s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);s.face('left');assert.equal((await s.action()).reason,'EXACT_SUPPORTED_PORT_REQUIRED');s.releaseAction();s.move('down');s.face('up');assert.equal((await s.action()).ok,false)});
 test(id+': pending locks moves, duplicate and cancel late completion ignored',async()=>{let resolve;const s=make(id,{loadScene:()=>new Promise(r=>resolve=r)});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);const p=s.action();assert.equal(s.move('down').reason,'INPUT_LOCKED');assert.equal((await s.action()).reason,'BUSY');s.cancel();resolve({sha256:c.sources[s.h.firstFloor].sha256});assert.equal((await p).reason,'STALE');assert.equal(s.scene,'exterior');assert.equal(s.portalTransfers,0)});
 test(id+': old late request cannot overwrite newer success',async()=>{const resolvers=[];const s=make(id,{loadScene:()=>new Promise(r=>resolvers.push(r))});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);const old=s.action();s.cancel();s.move('down');s.move('up');const current=s.action();resolvers[1]({sha256:c.sources[s.h.firstFloor].sha256});assert.equal((await current).ok,true);resolvers[0]({sha256:c.sources[s.h.firstFloor].sha256});assert.equal((await old).reason,'STALE');assert.equal(s.scene,s.h.firstFloor)});
 test(id+': closing during load invalidates pending transition',async()=>{let resolve;const s=make(id,{loadScene:()=>new Promise(r=>resolve=r)});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);const p=s.action();s.setDoorState('CLOSED');resolve({sha256:c.sources[s.h.firstFloor].sha256});assert.equal((await p).reason,'STALE');assert.equal(s.scene,'exterior')});
 test(id+': SHA error leaves source intact; controlled retry needs release and clearance',async()=>{let bad=true;const s=make(id,{loadScene:async t=>({sha256:bad?'bad':c.sources[t].sha256})});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);assert.equal((await s.action()).reason,'TARGET_SOURCE_PIN_MISMATCH');s.releaseAction();assert.equal((await s.action()).reason,'RELEASE_AND_LEAVE_TRIGGER_REQUIRED');bad=false;s.move('down');s.releaseAction();s.move('up');assert.equal((await s.action()).kind,'enter')});
 test(id+': unsupported landing rejects without invented foot adjustment',async()=>{const mm={...masks,[c.houses[id].firstFloor]:new Uint8Array(696*464)},s=make(id,{masks:mm});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);assert.equal((await s.action()).reason,'TARGET_FOOT_UNSUPPORTED');assert.equal(s.scene,'exterior')});
 test(id+': closed return rejects, explicit developer reset recovers, dispose is terminal',async()=>{const s=make(id);await enter(s);exitRoute(s);s.setDoorState('CLOSED');assert.equal((await s.action()).reason,'DOOR_CLOSED');s.reset();assert.equal(s.scene,'exterior');s.dispose();const old=s.snapshot();s.reset();s.cancel();s.setDoorState('OPEN');s.move('up');assert.equal((await s.action()).reason,'DISPOSED');assert.deepEqual(s.snapshot(),old)});
}
test('upper original2floor stairs contract/trigger/arrival and exits retained',async()=>{const s=make('upper');await enter(s);walk(s,c.floors.upper_1F.routes.entryArrival_stair);assert.equal((await s.action()).kind,'stairs');s.releaseAction();assert.deepEqual(s.foot,[348,278]);walk(s,c.floors.upper_2F.routes.stairArrival_stair);assert.equal((await s.action()).kind,'stairs');s.releaseAction();assert.deepEqual(s.foot,[444,250]);exitRoute(s);assert.equal((await s.action()).kind,'return');assert.equal(s.stairTransfers,2)});
test('family remains exactly one floor, no fabricated stair interaction',async()=>{const s=make('family');await enter(s);assert.equal(s.h.stairs.length,0);assert.equal((await s.action()).ok,false);assert.equal(s.safe('upper_2F',[348,278]),false)});
test('two unsupported/unassigned houses never construct session or call a loader',()=>{let calls=0;for(const h of c.unassigned)assert.throws(()=>make(h.id,{loadScene:()=>calls++}),/UNREGISTERED_HOME/);assert.equal(calls,0);assert.equal(masks.exterior[1375*5120+1572],1);assert.equal(masks.exterior[1210*5120+3312],0);assert.equal(c.unassigned.find(h=>h.id==='keeper_home').exteriorFoot,null)});
test('input direction and malformed coordinates fail without growing floor support',()=>{const s=make('upper'),before=s.foot.slice();assert.equal(s.move('warp').ok,false);assert.equal(s.safe('exterior',null),false);assert.equal(s.safe('exterior',[1.5,3]),false);assert.deepEqual(s.foot,before);assert.equal(s.setDoorState('maybe').ok,false)});
test('scene switch disposal invalidates load while shared UI ticket preserves latest message',async()=>{let resolve;const ticket=createUITicket(),s=make('upper',{loadScene:()=>new Promise(r=>resolve=r)});s.setDoorState('OPEN');walk(s,s.h.exteriorDoor.approachRoute);const old=ticket.begin(),pending=s.action();s.dispose();ticket.invalidate();const next=make('family');resolve({sha256:c.sources.upper_1F.sha256});assert.equal((await pending).reason,'STALE');assert.equal(ticket.isCurrent(old),false);assert.equal(next.scene,'exterior')});
test('viewer cancellation/visibility/house switch and old async UI-message guards retained',()=>{const s=fs.readFileSync(new URL('../viewer.mjs',import.meta.url),'utf8');for(const hook of ['pointercancel','pagehide','popstate','visibilitychange','resize','orientationchange','resetFrameBaseline()','ticket.invalidate()','if(!ticket.isCurrent(mine))return','session?.dispose()'])assert(s.includes(hook));for(const bad of ['localStorage','sessionStorage','worldCommand'])assert(!s.includes(bad));const r=s.slice(s.indexOf('function chooseHome'),s.indexOf('async function action'));assert(!r.includes('createJangmokEnvironment'));assert(!r.includes('environment?.setTime('))});
test('upper receipt distinguishes selected coordinate reuse from newly authored runtime interpreter',async()=>{const s=make('upper');await enter(s);walk(s,c.floors.upper_1F.routes.entryArrival_stair);await s.action();const r=s.receipts.at(-1);assert.equal(r.reusedSelectedTransition,true);assert.equal(r.newAuthoredRuntime,true);assert.equal(r.newAuthoredPlacement,false)});
